# Shinylive smoke-test app
# No external packages, no embedded research data, no server calls.

ui <- shiny::fluidPage(
  shiny::tags$head(
    shiny::tags$style(shiny::HTML("body{max-width:900px;margin:auto;padding:24px;font-family:system-ui}.ok{padding:12px;border-radius:8px;background:#e9f7ef;color:#155724;margin:12px 0}"))
  ),
  shiny::h2("Shinylive smoke test"),
  shiny::div(class="ok","If this page is interactive, Shiny and webR loaded correctly in the browser."),
  shiny::fileInput("file","Choose a local CSV file",accept=".csv"),
  shiny::sliderInput("bins","Histogram bins",5,50,15),
  shiny::plotOutput("plot",height="380px"),
  shiny::verbatimTextOutput("status"),
  shiny::downloadButton("download_example","Download tiny example CSV")
)

server <- function(input, output, session) {
  data <- shiny::reactive({
    if (is.null(input$file)) {
      data.frame(group=rep(c("A","B"),each=10),value=c(1:10,6:15))
    } else {
      utils::read.csv(input$file$datapath,check.names=FALSE)
    }
  })
  output$status <- shiny::renderPrint({
    x <- data()
    cat("Rows:",nrow(x),"\nColumns:",ncol(x),"\nR:",R.version.string,"\nPlatform:",R.version$platform)
  })
  output$plot <- shiny::renderPlot({
    x <- data(); numeric_cols <- names(x)[vapply(x,is.numeric,logical(1))]
    shiny::validate(shiny::need(length(numeric_cols)>0,"The CSV needs at least one numeric column."))
    graphics::hist(x[[numeric_cols[1]]],breaks=input$bins,col="#4C78A8",border="white",main=paste("Histogram of",numeric_cols[1]),xlab=numeric_cols[1])
  })
  output$download_example <- shiny::downloadHandler(
    filename=function()"shinylive_example.csv",
    content=function(file)utils::write.csv(data.frame(group=rep(c("A","B"),each=10),value=c(1:10,6:15)),file,row.names=FALSE)
  )
}

shiny::shinyApp(ui,server)
